            ["settings.secCenter"] = "Security Center",
            ["settings.secCenterHint"] = "See exactly what is protecting this wallet right now — Tor, kill-switch, auto-lock, backups and more, read live.",
            ["settings.openSecCenter"] = "Open Security Center",
            ["settings.cyber1"] = "Seed generated on-device from the OS cryptographic RNG — it is never transmitted anywhere.",
            ["settings.cyber2"] = "Vault at rest: Argon2id (memory-hard, m=64 MiB) derives the key, then AES-256-GCM authenticated encryption — tampering is detected, brute-forcing is throttled.",
            ["settings.cyber3"] = "Private keys are derived only for the moment of signing and then wiped from memory (CryptographicOperations.ZeroMemory); the seed is wiped on lock.",
            ["settings.cyber4"] = "Screenshot / screen-share guard: while the recovery phrase or Monero keys are on screen, the window renders black to capture software.",
