            ["settings.proxy"] = "CUSTOM PROXY (SOCKS5)",
            ["settings.proxyHint"] = "Prefer your own network path? Route every balance, price and broadcast request through your own SOCKS5 proxy — a VPN, an SSH tunnel or another Tor instance — instead of the bundled Tor. Enter host:port or socks5://host:port. This and Tor are mutually exclusive; turning one on switches the other off.",
