            ["buy.copyPrimary"] = "Hauptadresse kopieren",
            ["buy.providers"] = "ANBIETER — ÖFFNEN IN DEINEM BROWSER",
            ["buy.disclaimer"] = "Dies sind unabhängige Drittanbieter, der Bequemlichkeit halber gelistet — keine Empfehlungen, und Umbrella nimmt keine Gebühr. Es sind regulierte On-Ramps und verlangen einen Ausweis (KYC); Verfügbarkeit, Limits und Gebühren hängen von deinem Land ab. Prüfe stets, dass die eingefügte Empfangsadresse zu Coin/Netzwerk passt, bestätige den Betrag auf der Seite des Anbieters selbst und teile nie deine Wiederherstellungsphrase — kein On-Ramp braucht sie.",
            ["p2p.title"] = "P2P & DEX",
            ["p2p.desc"] = "Handle, ohne die Verwahrung abzugeben — On-Chain-DEXes und Peer-to-Peer-Treuhand. Deine Schlüssel verlassen nie dieses Gerät.",
            ["p2p.inWallet"] = "IN DER WALLET",
            ["p2p.swapCard"] = "Cross-Chain-Swaps (z. B. BTC ↔ ETH) laufen über THORChain-Vaults — ohne Verwahrung, ohne Konto, ohne verpackte IOUs. Coins bewegen sich On-Chain und landen wieder auf deinen eigenen Adressen.",
            ["p2p.openSwap"] = "Swap öffnen →",
            ["p2p.external"] = "EXTERN — ÖFFNEN IN DEINEM BROWSER",
            ["p2p.disclaimer"] = "Dies sind unabhängige Drittanbieter-Plattformen, der Bequemlichkeit halber gelistet — keine Empfehlungen, und Umbrella nimmt keine Gebühr und hält nichts. Jede lässt die Verwahrung bei dir (ein On-Chain-DEX oder P2P-Treuhand, den du mitunterzeichnest). Prüfe die Adressleiste stets selbst und denk daran: kein seriöser Handel braucht deine Wiederherstellungsphrase. Fiat-On-Ramps erfordern meist eine regulierte Börse und werden hier bewusst nicht gelistet.",
