            ["settings.hideBal"] = "GUTHABEN STANDARDMÄSSIG VERBERGEN",
            ["settings.hideBalHint"] = "Jede Entsperrung startet mit verborgenen Beträgen (••••), bis du zum Anzeigen tippst — nützlich in der Öffentlichkeit oder bei geteiltem Bildschirm.",
            ["settings.hideBalOn"] = "Beim Entsperren verborgen",
            ["settings.hideBalOff"] = "Beim Entsperren sichtbar",
            ["settings.cyber"] = "CYBERSICHERHEIT · AUF DIESEM PC",
            ["settings.cyberHint"] = "Alles, was diese Wallet lokal schützt. Kein Server ist daran beteiligt — das gesamte Sicherheitsmodell lebt auf deiner Maschine.",
            ["settings.secCenter"] = "Sicherheitszentrum",
            ["settings.secCenterHint"] = "Sieh live, was diese Wallet gerade schützt — Tor, Notausschalter, Auto-Sperre, Backups und mehr.",
            ["settings.openSecCenter"] = "Sicherheitszentrum öffnen",
            ["settings.cyber1"] = "Der Seed wird auf dem Gerät aus dem kryptografischen RNG des Betriebssystems erzeugt — er wird niemals irgendwohin übertragen.",
            ["settings.cyber2"] = "Vault im Ruhezustand: Argon2id (speicherhart, m=64 MiB) leitet den Schlüssel ab, dann authentifizierte AES-256-GCM-Verschlüsselung — Manipulation wird erkannt, Brute-Force gedrosselt.",
            ["settings.cyber3"] = "Private Schlüssel werden nur für den Moment des Signierens abgeleitet und dann aus dem Speicher gelöscht (CryptographicOperations.ZeroMemory); der Seed wird beim Sperren gelöscht.",
            ["settings.cyber4"] = "Screenshot-/Bildschirmfreigabe-Schutz: Während die Wiederherstellungsphrase oder Monero-Schlüssel auf dem Bildschirm sind, erscheint das Fenster für Aufnahmesoftware schwarz.",
            ["settings.cyber5"] = "Das Signieren nutzt die Referenz-Kryptografie der Chains (NBitcoin, Nethereum, BouncyCastle ed25519); jede Ableitung und der TON-Transfer sind per Unit-Test an offizielle Vektoren gebunden.",
            ["settings.cyber6"] = "Kein Konto, keine E-Mail, keine Telemetrie, keine Analytik. Die App kann deine Gelder nicht einfrieren, beschlagnahmen oder wiederherstellen — und niemand sonst auch nicht.",
            ["settings.privacyNet"] = "PRIVATSPHÄRE & NETZWERK",
            ["settings.priv1"] = "Kein Konto, keine E-Mail, keine Telemetrie, kein Analytik-SDK.",
            ["settings.priv2"] = "Seed und private Schlüssel verlassen diesen PC nie — es gibt keine serverseitige Kopie.",
            ["settings.priv3"] = "Guthaben- und Preisabfragen nutzen öffentliche Explorer. Standardmäßig sehen sie deine IP; aktiviere Tor unten, um diesen Verkehr über dein lokales Tor zu leiten, sodass sie stattdessen einen Tor-Ausgang sehen.",
            ["settings.endpoints"] = "ENDPUNKTE",
            ["settings.chains"] = "CHAINS",
            ["settings.tor"] = "TOR · VERBIRGT DEINE IP (INTEGRIERT)",
            ["settings.torHint"] = "Tor ist in Umbrella integriert — nichts zu installieren. Schalte es ein, und die Wallet startet ihren eigenen Tor-Client und leitet dann jede Guthaben-, Preis- und Broadcast-Anfrage darüber, sodass Explorer und RPC-Knoten einen Tor-Ausgang statt deiner IP sehen. Es läuft auf einem privaten Port (9250), sodass ein bereits genutzter Tor Browser unberührt bleibt, und wird mit der Wallet beendet.",
            ["settings.torOn"] = "Tor an",
            ["settings.torOff"] = "Tor aus",
            ["settings.moneroSvc"] = "MONERO-WALLET-DIENST (INTEGRIERT)",
            ["settings.moneroSvcHint"] = "Moneros eigener Wallet-Daemon ist in Umbrella integriert. Schalte ihn ein, und XMR wird eine vollwertige Münze — echtes Guthaben und echtes Senden — denn Monero-Beträge sind on-chain verborgen und nur durch Scannen mit deinem View Key lesbar. Deine Schlüssel bleiben auf diesem PC; nur der Daemon sieht sie, und er läuft über Tor, wenn Tor an ist. Der erste Scan dauert einige Minuten.",
            ["settings.moneroOn"] = "Monero an",
            ["settings.moneroOff"] = "Monero aus",
            ["settings.proxy"] = "EIGENER PROXY (SOCKS5)",
            ["settings.proxyHint"] = "Lieber ein eigener Netzwerkpfad? Leite jede Guthaben-, Preis- und Broadcast-Anfrage über deinen eigenen SOCKS5-Proxy — ein VPN, einen SSH-Tunnel oder eine andere Tor-Instanz — statt über das integrierte Tor. Gib host:port oder socks5://host:port ein. Dies und Tor schließen sich gegenseitig aus; eines einzuschalten schaltet das andere aus.",
            ["settings.proxyOn"] = "Meinen Proxy nutzen",
            ["settings.proxyOff"] = "Aus",
            ["settings.proxyApply"] = "Anwenden",
            ["settings.ipMode"] = "IP-VERSION",
            ["settings.ipModeHint"] = "Erzwinge ausgehende Verbindungen über IPv4 oder IPv6, oder überlasse die Wahl dem System. Gilt für direkte (Nicht-Proxy-)Verbindungen — nützlich in Netzwerken, in denen eine Variante defekt ist oder Daten preisgibt.",
            ["settings.clipboard"] = "ZWISCHENABLAGE AUTOM. LEEREN",
            ["settings.clipboardHint"] = "Löscht eine kopierte Adresse nach einer Weile automatisch aus der Zwischenablage, damit sie nicht für andere Apps oder Zwischenablage-Manager lesbar bleibt.",
            ["settings.lockMin"] = "BEIM MINIMIEREN SPERREN",
            ["settings.lockMinHint"] = "Sperrt den Tresor, sobald das Fenster minimiert wird, damit eine im Hintergrund offene Wallet niemand daneben oder beim Bildschirmteilen sieht. Zum Entsperren ist dein Passwort nötig.",
            ["settings.lockMinOn"] = "Beim Minimieren sperren",
            ["settings.lockMinOff"] = "Entsperrt lassen",
            ["settings.richData"] = "ERWEITERTE MARKTDATEN (COINGECKO)",
            ["settings.richDataHint"] = "Standardmäßig aus: die Wallet kontaktiert keine Dritten, bis du dies einschaltest. Aktiviere es, um Marktkapitalisierung, FDV und Volumen auf der Münzseite anzuzeigen — von CoinGecko über deine Tor/Proxy-Route.",
            ["settings.richOn"] = "Connector an",
            ["settings.richOff"] = "Aus (privat)",
            ["settings.documentation"] = "DOKUMENTATION",
            ["settings.openGuide"] = "Anleitung öffnen",
            ["settings.backupFile"] = "BACKUP-DATEI",
            ["settings.backupHint"] = "Speichert deine Vault, verknüpfte Adressen und Exchange-Schlüssel in einer Datei. Sie wird genau so verschlüsselt exportiert — die Datei ist ohne dein Vault-Passwort wertlos und kann aus demselben Grund nur mit diesem Passwort wiederhergestellt werden. Es gibt keine Wiederherstellung, wenn du sie verlierst.",
            ["settings.saveBackup"] = "Backup speichern…",
            ["settings.restoreBackup"] = "Aus Backup wiederherstellen…",
            ["settings.restoreNote"] = "Das Wiederherstellen ersetzt die Wallet auf diesem PC. Die vorherige Vault wird daneben als .replaced-Datei behalten statt gelöscht, sodass eine irrtümliche Wiederherstellung rückgängig gemacht werden kann.",
            ["settings.verifyBackup"] = "Backup prüfen",
            ["settings.verifyBackupPw"] = "Vault-Passwort",
            ["settings.verifyBackupBtn"] = "Backup-Datei prüfen",
            ["settings.pwVsPhrase"] = "Das Vault-Passwort entsperrt diese App auf diesem PC. Deine 12/24-Wort-Wiederherstellungsphrase stellt die Wallet überall wieder her — und ist das Einzige, das das kann. Bewahre sie offline auf; niemand kann sie für dich wiederherstellen.",
            ["settings.recovery"] = "WIEDERHERSTELLUNGSPHRASE",
            ["settings.recoveryHint"] = "Gib dein Vault-Passwort ein, um die Wiederherstellungsphrase zu entschlüsseln und anzuzeigen. Sie bleibt verborgen, bis das Passwort korrekt ist.",
            ["settings.keysIntro"] = "Hier gibt es zwei verschiedene Dinge. Deine 24-Wort-Wiederherstellungsphrase unten stellt deine ganze Wallet wieder her — jede Münze, einschließlich einer frischen Monero-Wallet — in Umbrella oder jeder kompatiblen Wallet. Diese Phrase allein ist dein Backup. Die Monero-Schlüssel weiter unten sind optional und nur zum Importieren deines Monero in Feather oder die Monero-CLI; die meisten brauchen sie nie.",
            ["settings.moneroAdvanced"] = "ERWEITERT · MONERO-SCHLÜSSEL (OPTIONAL)",
            ["settings.vaultPassword"] = "Vault-Passwort",
            ["settings.revealPhrase"] = "Wiederherstellungsphrase anzeigen",
            ["settings.hidePhrase"] = "Phrase verbergen",
            ["settings.moneroExport"] = "MONERO · SCHLÜSSEL EXPORTIEREN",
            ["settings.moneroExportHint"] = "Umbrella leitet ein echtes Monero-Konto ab und kann darauf empfangen, aber Monero-Guthaben sind on-chain verborgen und aus einem öffentlichen Explorer nicht lesbar — und Umbrella baut keine XMR-Transaktionen. Um das Guthaben zu sehen oder auszugeben, trage diese drei Werte über \"Aus Schlüsseln wiederherstellen\" in Feather (oder monero-wallet-cli) ein. Gib zuerst oben dein Vault-Passwort ein.",
            ["settings.revealMoneroKeys"] = "Monero-Schlüssel anzeigen",
            ["settings.primaryAddress"] = "PRIMÄRE ADRESSE",
            ["settings.spendKey"] = "GEHEIMER SPEND KEY  ·  wie deinen Seed behandeln",
            ["settings.viewKey"] = "GEHEIMER VIEW KEY",
            ["settings.hideKeys"] = "Schlüssel verbergen",
            ["settings.dangerZone"] = "GEFAHRENZONE",
            ["settings.dangerHint"] = "Das löscht deine Wallet NICHT aus der Blockchain - eine Wallet lebt in ihrer Wiederherstellungsphrase, nicht auf diesem PC, und niemand kann sie löschen. Es löscht die lokale Kopie auf diesem Gerät: den verschlüsselten Seed, jede zusätzliche Wallet, deine Einstellungen und Profilbilder, beobachtete Adressen, gespeicherte Börsenschlüssel, dein Adressbuch, deine privaten Transaktionsnotizen, das Aktivitätsprotokoll, zwischengespeicherte Guthaben und Preise sowie die Monero-Wallet. Übrig bleiben nur die App selbst und der mitgelieferte Tor-Client. Gib deine 24 Wörter auf einem beliebigen Gerät erneut ein, um die Mittel zurückzuholen.",
            ["settings.danger1"] = "Dies ist unumkehrbar. Es gibt keinen Support und kein Server-Backup, das die Wallet zurückbringen könnte.",
            ["settings.danger2"] = "Nur deine aufgeschriebene 24-Wörter-Wiederherstellungsphrase kann die Gelder wiederherstellen — in dieser oder jeder BIP39-Wallet. Stelle zuerst sicher, dass du sie auf Papier hast.",
            ["settings.danger3"] = "Dein Adressbuch und deine privaten Transaktionsnotizen verschwinden mit. Bis zu dieser Version blieben sie nach dem Löschen auf der Festplatte, und das Adressbuch wird im Klartext gespeichert - was es zu dem Teil dieser Wallet macht, dessen Entfernung am meisten zählt.",
            ["settings.dangerConfirmHint"] = "Gib das Bestätigungswort ein, um fortzufahren. Erwäge davor, ein verschlüsseltes Backup zu exportieren (Tab Backup) oder deine Phrase anzuzeigen (Tab Backup).",
